// Ordinary tests consume checked-in bytes without Java or a broker.
import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';
import 'package:kafka_client/kafka_protocol.dart';
import 'package:test/test.dart';

void main() {
  final golden = jsonDecode(
          File('test/fixtures/group_membership_java.json').readAsStringSync())
      as Map<String, dynamic>;
  List<int> bytes(String key) {
    final hex = golden[key] as String;
    return [
      for (var i = 0; i < hex.length; i += 2)
        int.parse(hex.substring(i, i + 2), radix: 16)
    ];
  }

  List<int> body(KafkaRequest r) {
    final all = r.toBytes();
    final clientLength =
        ByteData.sublistView(Uint8List.fromList(all)).getInt16(12);
    return all.sublist(14 + clientLength);
  }

  List<int> response(KafkaRequest r, String key) => [
        ...(ByteData(4)..setInt32(0, r.correlationId)).buffer.asUint8List(),
        ...bytes(key)
      ];
  const blob = [0, 1, 2, 255];
  test('official Java request bodies: Join4 Sync2 Heartbeat2 Leave2 Commit6',
      () {
    final requests = <String, KafkaRequest>{
      'joinRequestV4': JoinGroupRequest('grπ',
          sessionTimeoutMs: 10000,
          rebalanceTimeoutMs: 20000,
          memberId: 'm',
          protocols: [GroupJoinProtocol('range', blob)]),
      'syncRequestV2': SyncGroupRequest('grπ',
          generationId: 7,
          memberId: 'm',
          assignments: [GroupAssignment('m', blob)]),
      'heartbeatRequestV2':
          HeartbeatRequest('grπ', generationId: 7, memberId: 'm'),
      'leaveRequestV2': LeaveGroupRequest('grπ', memberId: 'm'),
      'commitRequestV6': MemberOffsetCommitRequest('grπ', 'tπ', {2: 123},
          generationId: 7, memberId: 'm', metadata: 'savedπ'),
    };
    for (final entry in requests.entries) {
      expect(body(entry.value), bytes(entry.key), reason: entry.key);
    }
  });
  test('official Java responses retain fields and raw errors', () {
    final join = JoinGroupRequest('grπ',
        sessionTimeoutMs: 10000,
        rebalanceTimeoutMs: 20000,
        protocols: [GroupJoinProtocol('range', blob)]);
    final j = join.parseResponse(response(join, 'joinResponseV4'));
    expect(j.errorCode, 0);
    expect(j.generationId, 7);
    expect(j.protocolName, 'range');
    expect(j.leaderId, 'm');
    expect(j.memberId, 'm');
    expect(j.members.single.memberId, 'm');
    expect(j.members.single.metadata, blob);
    final sync = SyncGroupRequest('grπ', generationId: 7, memberId: 'm');
    final s = sync.parseResponse(response(sync, 'syncResponseV2'));
    expect(s.errorCode, 0);
    expect(s.assignment, blob);
    final heartbeat = HeartbeatRequest('grπ', generationId: 7, memberId: 'm');
    expect(
        heartbeat
            .parseResponse(response(heartbeat, 'heartbeatResponseV2'))
            .errorCode,
        22);
    final leave = LeaveGroupRequest('grπ', memberId: 'm');
    expect(
        leave.parseResponse(response(leave, 'leaveResponseV2')).errorCode, 25);
  });
  for (var version = 0; version <= 3; version++) {
    test('official Java consumer metadata v$version, nullable user data', () {
      for (final nullable in [false, true]) {
        final suffix = '${nullable ? 'Null' : ''}V$version';
        final sub = ConsumerGroupSubscription(['tπ'],
            version: version,
            userData: nullable ? null : blob,
            ownedPartitions: nullable || version < 1
                ? {}
                : {
                    'tπ': [2]
                  },
            generationId: nullable || version < 2 ? -1 : 7,
            rackId: nullable || version < 3 ? null : 'rackπ');
        final assignment = ConsumerGroupAssignment({
          'tπ': [2]
        }, version: version, userData: nullable ? null : blob);
        expect(sub.toBytes(), bytes('subscription$suffix'));
        expect(assignment.toBytes(), bytes('assignment$suffix'));
        final decoded =
            ConsumerGroupSubscription.fromBytes(bytes('subscription$suffix'));
        expect(decoded.topics, ['tπ']);
        expect(decoded.version, version);
        expect(decoded.userData, nullable ? null : blob);
        expect(decoded.generationId, nullable || version < 2 ? -1 : 7);
        expect(decoded.rackId, nullable || version < 3 ? null : 'rackπ');
        expect(decoded.toBytes(), bytes('subscription$suffix'));
        final assigned =
            ConsumerGroupAssignment.fromBytes(bytes('assignment$suffix'));
        expect(assigned.partitions, {
          'tπ': [2]
        });
        expect(assigned.toBytes(), bytes('assignment$suffix'));
      }
    });
  }
